pattern = [[9,9,8,9,9,2,2,1,9],[9,2,9,9,2,9,9,9,9],[9,1,8,2,1,9,9,9,9],[9,9,2,9,9,9,9,9,9],[9,9,9,9,9,9,9,9,9]]
H,W=17,29
grid=[[9]*W for _ in range(H)]
for r in (5,11): grid[r]=[3]*W
for c in (9,19):
    for r in range(H): grid[r][c]=3
for r0 in (0,6,12):
    for c0 in (0,10,20):
        for i,row in enumerate(pattern):
            for j,v in enumerate(row):
                if v != 9: grid[r0+i][c0+j]=v
print('\n'.join(' '.join(map(str,row)) for row in grid))
